<script lang="ts">
 import { onMount } from 'svelte'; import { page } from '$app/state'; import { base } from '$app/paths'; import { db } from '$lib/db'; import type { Drawing, Stage, PaletteSet } from '$lib/types'; import Timeline from '$lib/components/Timeline.svelte'; import CompareSlider from '$lib/components/CompareSlider.svelte'; import PaletteStrip from '$lib/components/PaletteStrip.svelte'; import { exportGif } from '$lib/export/gif';
 let drawing=$state<Drawing>(),stages=$state<Stage[]>([]),urls=$state<Record<string,string>>({}),selected=$state(''),paletteSet=$state<PaletteSet>(),paletteSets=$state<PaletteSet[]>([]),busy=$state(false),delay=$state(600),error=$state('');
 async function refresh(){const id=page.params.id;if(!id){error='This drawing could not be found.';return;}drawing=await db.drawings.get(id);stages=await db.stages.where('drawingId').equals(id).sortBy('createdAt');if(!drawing)error='This drawing could not be found.';else if(stages.length)selected=stages.at(-1)!.id;paletteSets=await db.paletteSets.toArray();paletteSet=drawing?.paletteSetId?await db.paletteSets.get(drawing.paletteSetId):undefined;urls=Object.fromEntries(stages.map(s=>[s.id,URL.createObjectURL(s.flatBlob)]));}
 onMount(()=>{void refresh();return()=>Object.values(urls).forEach(URL.revokeObjectURL);});
 let current=$derived(stages.find(s=>s.id===selected));
 async function deleteStage(s:Stage){if(!confirm('Delete this stage?'))return;await db.stages.delete(s.id);await refresh();}
 async function selectPaletteSet(id:string){if(!drawing)return;await db.drawings.update(drawing.id,{paletteSetId:id||undefined});drawing={...drawing,paletteSetId:id||undefined};paletteSet=paletteSets.find(s=>s.id===id);}
 async function makeGif(){if(stages.length<2)return;busy=true;try{const blob=await exportGif(stages,delay),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${drawing?.title??'skepanion'}.gif`;a.click();URL.revokeObjectURL(url);}catch(e){error=e instanceof Error?e.message:'GIF export failed.';}finally{busy=false;}}
</script>
<div class="app drawing-page"><header class="topbar"><a class="brand" href={`${base}/`}><span class="brand-mark">✳</span>Skepanion</a><nav class="nav"><a href={`${base}/palettes`}>My colors</a><a href={`${base}/monthly`}>Monthly</a><a href={`${base}/backup`}>Backup</a></nav></header>
{#if error}<div class="card">{error} <a href={`${base}/`}>Back to drawings</a></div>{:else if drawing}<a href={`${base}/`} class="muted back-link">← All drawings</a><div class="row page-title-row" style="justify-content:space-between"><div><p class="eyebrow">Drawing timeline</p><h1>{drawing.title}</h1></div><a class="button" href={`${base}/drawing/${drawing.id}/add`}>＋ Add stage</a></div>
<section class="section progress-section"><div class="row section-heading"><h2>Progress</h2>{#if stages.length}<span class="stage-count">{stages.length} {stages.length===1?'stage':'stages'}</span>{/if}</div>{#if stages.length===0}<div class="card empty-card"><div class="empty-mark" aria-hidden="true">✳</div><h2>Add your first photo</h2><p class="muted">A simple, repeatable photo makes it easier to see your progress.</p><a class="button" href={`${base}/drawing/${drawing.id}/add`}>Add a stage</a></div>{:else}<Timeline {stages} bind:selected/><div class="card compare-card">{#if stages.length>1}<CompareSlider before={urls[stages[0].id]} after={urls[current?.id??stages.at(-1)!.id]} label="Compare the first and selected stage"/><p class="muted compare-hint">The first stage is shown against your selected stage. Drag across the image to compare.</p>{:else}<img src={urls[stages[0].id]} alt="Current drawing stage" class="single-stage-image"/>{/if}</div>
<div class="row" style="margin-top:12px"><label class="field" style="max-width:180px;margin:0">GIF frame delay<select bind:value={delay}><option value={300}>300 ms</option><option value={600}>600 ms</option><option value={1000}>1000 ms</option></select></label><button class="button secondary" disabled={stages.length<2||busy} onclick={()=>void makeGif()}>{busy?'Creating GIF…':'↓ Export progress GIF'}</button>{#if current}<button class="button danger" onclick={()=>void deleteStage(current)}>Delete selected stage</button>{/if}</div>{/if}</section>
{#if stages.length}<section class="section palette-section"><div class="row palette-heading" style="justify-content:space-between"><div><p class="eyebrow">The color story</p><h2>Colors over time</h2></div>{#if paletteSets.length}<label class="field palette-select"><span>Mixing suggestions use</span><select value={drawing.paletteSetId??''} onchange={(e)=>void selectPaletteSet(e.currentTarget.value)}><option value="">No color set</option>{#each paletteSets as set}<option value={set.id}>{set.name}</option>{/each}</select></label>{/if}</div>{#each stages as stage}<article class="card palette-stage"><div class="row stage-meta" style="justify-content:space-between"><b>{new Date(stage.createdAt).toLocaleDateString()}</b>{#if stage.note}<span class="muted">{stage.note}</span>{/if}</div><div class="palette-stage-content"><PaletteStrip palette={stage.palette} paletteSet={paletteSet}/></div></article>{/each}</section>{/if}{/if}</div>
